mapper.update:
UPDATE tb_voucher_order
SET status = 2,
    pay_type = #{payType},
    pay_time = NOW(3),
    update_time = NOW(3)
WHERE id = #{orderId}
  AND user_id = #{userId}
  AND voucher_id = #{voucherId}
  AND status = 1
  AND expire_time > NOW(3)

UPDATE tb_voucher_order
SET status = 4, update_time = NOW(3)
WHERE id = #{orderId}
  AND user_id = #{userId} AND voucher_id = #{voucherId}
  AND status = 1
  AND expire_time <= NOW(3)

mapper.select:
SELECT id FROM tb_voucher_order
WHERE status = 1 AND expire_time <= NOW(3) AND id > #{afterId}
ORDER BY id LIMIT #{limit}
